p2=(chart_top+305, chart_top+560)
p3=(chart_top+610, chart_top+930)
axis_y=chart_top+955

def x_year(y):
    return x0 + (float(y)-2016)/(2024-2016)*(x1-x0)

def x_period(p):
    year=int(p[:4]); half=p[-2:]
    val=year + (0.25 if half=='H1' else 0.75)
    return x_year(val)

def y_scale(v, vmin, vmax, top, bot):
    return bot - (v-vmin)/(vmax-vmin)*(bot-top)

def points_line(rows, xfun, yfun, field):
    return ' '.join(f"{xfun(r):.1f},{yfun(r[field]):.1f}" for r in rows)

def step_path(rows, field, yfun):
    pts=[]
    for i,r in enumerate(rows):
        x=x_period(r['period']); y=yfun(r[field])
        if i==0: pts.append(f"M {x:.1f} {y:.1f}")
        else:
            prev_y=yfun(rows[i-1][field])
            pts.append(f"L {x:.1f} {prev_y:.1f} L {x:.1f} {y:.1f}")
    return ' '.join(pts)

def polyline(rows, field, yfun):
    return ' '.join(f"{x_year(r['year']):.1f},{yfun(r[field]):.1f}" for r in rows)

def text(x,y,s,cls='',anchor='start',extra=''):
    return f'<text x="{x:.1f}" y="{y:.1f}" class="{cls}" text-anchor="{anchor}" {extra}>{html.escape(str(s))}</text>'

def line(xa,ya,xb,yb,cls='',extra=''):
    return f'<line x1="{xa:.1f}" y1="{ya:.1f}" x2="{xb:.1f}" y2="{yb:.1f}" class="{cls}" {extra}/>'

def circle(x,y,r,cls='',extra=''):
    return f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{r}" class="{cls}" {extra}/>'

def grid(panel, ticks, vmin, vmax, label_fmt=lambda v: str(v)):
